const tabId = 2017691829;

async function searchAmazon(query) {
  await tool.navigate({ tabId, url: `https://www.amazon.com/s?k=${encodeURIComponent(query)}` });
  await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 10000 });
  return await browserjs(tabId, () => {
    const items = [];
    const elements = document.querySelectorAll("[data-component-type='s-search-result']");
    for (const el of elements) {
      const titleEl = el.querySelector("h2 a span") || el.querySelector("h2");
      const linkEl = el.querySelector("h2 a");
      const priceWhole = el.querySelector(".a-price-whole")?.textContent?.trim();
      const priceFraction = el.querySelector(".a-price-fraction")?.textContent?.trim();
      const rating = el.querySelector(".a-icon-alt")?.textContent?.trim();
      const reviews = el.querySelector(".s-underline-text")?.textContent?.trim();
      if (titleEl && linkEl) {
        items.push({
          title: titleEl.textContent.trim(),
          url: linkEl.href.split("?")[0],
          price: priceWhole ? `$${priceWhole}${priceFraction ? '.' + priceFraction : ''}` : el.querySelector(".a-price .a-offscreen")?.textContent || "not shown",
          rating,
          reviews
        });
      }
    }
    return items;
  });
}

