      if (seen.has(asin)) continue;
      seen.add(asin);

      const titleEl = card.querySelector("h2") || card.querySelector("a.a-text-normal");
      const linkEl = card.querySelector("h2 a") || card.querySelector("a[href*='/dp/']");
