// Let's search Target directly for Sunbeam, Beautyrest, and Biddeford
async function searchTarget(term) {
  await tool.navigate({ tabId, url: `https://www.target.com/s?searchTerm=${encodeURIComponent(term)}` });
  await tool.wait_for({ tabId, condition: "load_state", value: "domcontentloaded", timeout_ms: 10000 });
  return await browserjs(tabId, () => {
    const links = Array.from(document.querySelectorAll("a[href*='/p/']"));
    const seen = new Set();
    const items = [];
    for (const a of links) {
      const text = a.innerText.replace(/\n+/g, ' ').trim();
      const href = a.href;
      if (text.length > 15 && !seen.has(href)) {
        seen.add(href);
        items.push({ title: text.slice(0, 120), url: href });
      }
    }
    return items;
  });
}

